import re

def semver_cmp(a, b):
    def parse(version):
        match = re.match(r"(\d+(?:\.\d+)*)(-.*)?$", version)
        if not match:
            raise ValueError("Invalid version format")
        main_version = list(map(int, match.group(1).split('.')))
        prerelease = match.group(2) or ""
        return main_version, prerelease

    a_main, a_prerelease = parse(a)
    b_main, b_prerelease = parse(b)

    # Compare main versions numerically
    for am, bm in zip(a_main, b_main):
        if am > bm:
            return 1
        elif am < bm:
            return -1

    # If one version has fewer segments, treat missing as 0
    len_a = len(a_main)
    len_b = len(b_main)
    if len_a > len_b:
        for i in range(len_b, len_a):
            if a_main[i] != 0:
                return 1
    elif len_a < len_b:
        for i in range(len_a, len_b):
            if b_main[i] != 0:
                return -1

    # Versions with equal main are compared by prerelease
    if a_prerelease and not b_prerelease:
        return -1
    elif not a_prerelease and b_prerelease:
        return 1
    else:
        return (a_prerelease > b_prerelease) - (a_prerelease < b_prerelease)
```

